{
  "title": "How to Build a Campfire",
  "steps": [
    {
      "instruction": "Gather your materials: tinder (small, easily ignitable material), kindling (small sticks), and fuel wood (larger logs)."
    },
    {
      "instruction": "Arrange the tinder in the center, surrounded by kindling in a teepee or log cabin structure, then lean larger fuel wood against the kindling."
    },
    {
      "instruction": "Carefully light the tinder at the base of the structure, allowing the flame to spread to the kindling and then to the larger fuel wood."
    }
  ]
}
